command:
C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe -NoProfile -Command "`$u='http://127.0.0.1:3080/v3/projects/CampusNetwork_04/nodes/AGG_SW_02/command?cmd=display%20current-configuration'
`$lines=(Invoke-RestMethod -Uri `$u).output -split '\r?\n'
`$take=`$false
foreach(`$l in `$lines) {
 if(`$l -match '^interface ') {`$take=(`$l -match '^interface HundredGigE1/0/[1-7]`$')}
 if(`$l -match '^(sysname|stp | stp|undo stp|vlan | region-name| revision-level| instance [0-9]+ vlan)' -or `$take) {Write-Output `$l}
}"
